import { readFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import {
  ADPCM_BLOCK_PCM_BYTES, ADPCM_BLOCK_SAMPLES, ADPCM_INDEX_MAX, ADPCM_PREFIX_BYTES, AdpcmAssembler, adpcmPayloadLength,
  adpcmStepSize, assembleAdpcm, decodeAdpcmBlock, encodeAdpcmBlock,
} from './adpcm.js'

// The vectors are generated by devices/harness-device/firmware/scripts/gen_adpcm_vectors.py from the block description in
// docs/specs/cable-wifi-link.md, not from this codec or from the firmware's. The firmware's C test asserts against the
// same file. See cableFrame.spec.ts for the pattern.
const VECTORS = join(dirname(fileURLToPath(import.meta.url)), 'vectors', 'adpcm_ima.txt')

const hex = (text: string): Uint8Array => Uint8Array.from(Buffer.from(text, 'hex'))
const pcmOf = (text: string): Int16Array => {
  const raw = Buffer.from(text, 'hex')
  return Int16Array.from({ length: raw.length / 2 }, (_, i) => raw.readInt16LE(i * 2))
}
const pcmHex = (buf: Buffer): string => buf.toString('hex')

interface Vectors {
  enc: { name: string; pcm: Int16Array; indexIn: number; seq: number; flags: number; payload: string; indexOut: number }[]
  dec: { name: string; payload: string; pcm: Int16Array }[]
  gap: { name: string; payloads: Uint8Array[]; pcm: string }[]
  bad: { name: string; payload: string }[]
}
function load(): Vectors {
  const v: Vectors = { enc: [], dec: [], gap: [], bad: [] }
  for (const line of readFileSync(VECTORS, 'utf8').split('\n')) {
    const text = line.replace(/\r$/, '')
    if (!text || text.startsWith('#')) continue
    const f = text.split('\t')
    if (f[0] === 'enc') v.enc.push({ name: f[1], pcm: pcmOf(f[2]), indexIn: +f[3], seq: +f[4], flags: +f[5], payload: f[6], indexOut: +f[7] })
    else if (f[0] === 'dec') v.dec.push({ name: f[1], payload: f[2], pcm: pcmOf(f[3]) })
    else if (f[0] === 'gap') v.gap.push({ name: f[1], payloads: f[2].split(',').map(hex), pcm: f[3] })
    else if (f[0] === 'bad') v.bad.push({ name: f[1], payload: f[2] })
    else throw new Error(`unreadable vector line: ${f[0]}`)
  }
  return v
}
const vectors = load()

describe('ADPCM vectors', () => {
  it('has the cases the spec lists', () => {
    expect(vectors.enc.length).toBeGreaterThanOrEqual(20)
    expect(vectors.dec.length).toBeGreaterThanOrEqual(8)
    expect(vectors.gap.length).toBeGreaterThanOrEqual(5)
    expect(vectors.bad.length).toBeGreaterThanOrEqual(10)
  })

  describe.each(vectors.enc)('enc $name', (v) => {
    it('encodes to the vector byte for byte and carries the index', () => {
      const out = encodeAdpcmBlock(v.pcm, v.indexIn, v.seq, v.flags)
      expect(Buffer.from(out.payload).toString('hex')).toBe(v.payload)
      expect(out.indexOut).toBe(v.indexOut)
    })
    it('decodes back to n samples that start on the first sample exactly', () => {
      const r = decodeAdpcmBlock(hex(v.payload))
      expect(r.ok).toBe(true)
      if (!r.ok) return
      expect(r.block.n).toBe(v.pcm.length)
      expect(r.block.samples.length).toBe(v.pcm.length)
      expect(r.block.samples[0]).toBe(v.pcm[0])
      expect(r.block).toMatchObject({ seq: v.seq, flags: v.flags, indexStart: v.indexIn, indexEnd: v.indexOut })
    })
  })

  describe.each(vectors.dec)('dec $name', (v) => {
    it('decodes to the vector samples', () => {
      const r = decodeAdpcmBlock(hex(v.payload))
      expect(r.ok).toBe(true)
      if (r.ok) expect(Array.from(r.block.samples)).toEqual(Array.from(v.pcm))
    })
  })

  describe.each(vectors.gap)('gap $name', (v) => {
    it('assembles to the vector PCM', () => {
      expect(pcmHex(assembleAdpcm(v.payloads))).toBe(v.pcm)
    })
  })

  describe.each(vectors.bad)('bad $name', (v) => {
    it('is rejected', () => {
      expect(decodeAdpcmBlock(hex(v.payload)).ok).toBe(false)
    })
    it('is rejected the same way inside a larger buffer (no read past the view)', () => {
      const raw = hex(v.payload)
      const big = new Uint8Array(raw.length + 600).fill(0x11)
      big.set(raw, 100)
      expect(decodeAdpcmBlock(big.subarray(100, 100 + raw.length)).ok).toBe(false)
    })
  })
})

describe('ADPCM codec properties', () => {
  it('knows the payload length table', () => {
    expect([0, 1, 2, 9, 10, 505, 506].map(adpcmPayloadLength)).toEqual([0, 9, 13, 13, 17, 261, 0])
    expect(ADPCM_BLOCK_PCM_BYTES).toBe(ADPCM_BLOCK_SAMPLES * 2)
    expect(adpcmStepSize(0)).toBe(7)
    expect(adpcmStepSize(ADPCM_INDEX_MAX)).toBe(32767)
    expect(adpcmStepSize(ADPCM_INDEX_MAX + 1)).toBe(0)
  })

  it('stays inside one step over 100000 random blocks wherever one code can reach, with a lossless first sample', () => {
    // xorshift32, the generator of test_cable_transport.c.
    let rng = 0xd00e5193
    const word = (): number => {
      rng ^= rng << 13; rng >>>= 0
      rng ^= rng >>> 17
      rng ^= rng << 5; rng >>>= 0
      return rng
    }
    const adjust = [-1, -1, -1, -1, 2, 4, 6, 8]
    let inReach = 0
    for (let block = 0; block < 100_000; block++) {
      const n = 1 + (word() % ADPCM_BLOCK_SAMPLES)
      const kind = word() % 4
      let walk = (word() >>> 16) - 32768
      const pcm = new Int16Array(n)
      for (let i = 0; i < n; i++) {
        if (kind === 0) pcm[i] = (word() >>> 16) - 32768
        else if (kind === 1) { walk = Math.max(-32768, Math.min(32767, walk + (word() % 401) - 200)); pcm[i] = walk }
        else if (kind === 2) pcm[i] = ((word() >>> 16) & 0x3f) - 32
        else pcm[i] = Math.floor(i / 7) % 2 ? 30000 : -30000
      }
      const indexIn = word() % (ADPCM_INDEX_MAX + 1)
      const { payload, indexOut } = encodeAdpcmBlock(pcm, indexIn, block & 0xffff, 0)
      expect(payload.length).toBe(adpcmPayloadLength(n))
      const r = decodeAdpcmBlock(payload)
      if (!r.ok) throw new Error(`block ${block} refused: ${r.reason}`)
      expect(r.block.n).toBe(n)
      expect(r.block.indexEnd).toBe(indexOut)
      expect(r.block.samples[0]).toBe(pcm[0])
      let index = indexIn
      for (let i = 1; i < n; i++) {
        const code = (payload[9 + ((i - 1) >> 1)] >> (((i - 1) & 1) * 4)) & 15
        const step = adpcmStepSize(index)
        if (Math.abs(pcm[i] - r.block.samples[i - 1]) * 2 <= step * 3) {
          inReach++
          if (Math.abs(pcm[i] - r.block.samples[i]) > step) {
            throw new Error(`block ${block} sample ${i}: error ${Math.abs(pcm[i] - r.block.samples[i])} above step ${step}`)
          }
        }
        index = Math.max(0, Math.min(ADPCM_INDEX_MAX, index + adjust[code & 7]))
      }
    }
    expect(inReach).toBeGreaterThan(1_000_000)
  }, 60_000)

  it('refuses every wrong length, count and index, whatever the buffer holds', () => {
    for (const n of [0, 1, 2, 8, 9, 10, 17, 100, 504, 505, 506, 1000, 65535]) {
      for (let len = 0; len <= 270; len++) {
        const p = new Uint8Array(len)
        if (len >= 4) { p[2] = n & 0xff; p[3] = n >> 8 }
        const valid = n >= 1 && n <= 505 && len === adpcmPayloadLength(n)
        const r = decodeAdpcmBlock(p)
        expect(r.ok, `n=${n} len=${len}`).toBe(valid)
        if (r.ok) expect(r.block.samples.length).toBe(n)
      }
    }
    for (let index = 80; index < 256; index++) {
      const p = Uint8Array.from([0, 0, 9, 0, 0, 0, 0, index, 0, 0x11, 0x11, 0x11, 0x11])
      expect(decodeAdpcmBlock(p).ok).toBe(index <= ADPCM_INDEX_MAX)
    }
    expect(decodeAdpcmBlock(new Uint8Array(0))).toEqual({ ok: false, reason: 'short' })
    expect(decodeAdpcmBlock(Uint8Array.from([0, 0, 0, 0, 0]))).toEqual({ ok: false, reason: 'count' })
    expect(decodeAdpcmBlock(Uint8Array.from([0, 0, 9, 0, 0]))).toEqual({ ok: false, reason: 'length' })
    expect(decodeAdpcmBlock(Uint8Array.from([0, 0, 1, 0, 0, 0, 0, 89, 0]))).toEqual({ ok: false, reason: 'index' })
  })

  it('does not look at the reserved byte, the high flag bits or the pad nibbles', () => {
    const base = encodeAdpcmBlock(Int16Array.from([100, 200, 300]), 10, 3, 1).payload
    const noisy = Uint8Array.from(base)
    noisy[4] = 0xff // flags: the other bits are ignored on receive
    noisy[8] = 0xff // reserved
    noisy[noisy.length - 1] |= 0xf0 // pad nibbles (n = 3 uses two codes; the rest of the group is padding)
    const a = decodeAdpcmBlock(base), b = decodeAdpcmBlock(noisy)
    expect(a.ok && b.ok).toBe(true)
    if (a.ok && b.ok) expect(Array.from(b.block.samples)).toEqual(Array.from(a.block.samples))
  })

  it('encoder refuses a bad argument instead of writing a block', () => {
    expect(() => encodeAdpcmBlock(new Int16Array(0), 0, 0, 0)).toThrow(RangeError)
    expect(() => encodeAdpcmBlock(new Int16Array(506), 0, 0, 0)).toThrow(RangeError)
    expect(() => encodeAdpcmBlock(new Int16Array(10), 89, 0, 0)).toThrow(RangeError)
    expect(() => encodeAdpcmBlock(new Int16Array(10), -1, 0, 0)).toThrow(RangeError)
    expect(() => encodeAdpcmBlock(new Int16Array(10), 0, 65536, 0)).toThrow(RangeError)
    expect(() => encodeAdpcmBlock(new Int16Array(10), 0, 0, 256)).toThrow(RangeError)
  })

  it('gives the standard IMA values for hand-worked codes', () => {
    // pred 0, index 0 (step 7), code 7: 7>>3 + 7>>2 + 7>>1 + 7 = 0 + 1 + 3 + 7 = 11.
    const up = decodeAdpcmBlock(Uint8Array.from([0, 0, 2, 0, 0, 0, 0, 0, 0, 0x07, 0, 0, 0]))
    expect(up.ok && Array.from(up.block.samples)).toEqual([0, 11])
    const down = decodeAdpcmBlock(Uint8Array.from([0, 0, 2, 0, 0, 0, 0, 0, 0, 0x0f, 0, 0, 0]))
    expect(down.ok && Array.from(down.block.samples)).toEqual([0, -11])
    // Clamp at the top: pred 32767, index 88, code 7.
    const top = decodeAdpcmBlock(Uint8Array.from([0, 0, 2, 0, 0, 0xff, 0x7f, 88, 0, 0x07, 0, 0, 0]))
    expect(top.ok && Array.from(top.block.samples)).toEqual([32767, 32767])
  })
})

describe('AdpcmAssembler', () => {
  const sine = Int16Array.from({ length: 505 }, (_, i) => Math.round(8000 * Math.sin(i / 5)))
  const block = (seq: number, n = 505) => encodeAdpcmBlock(sine.subarray(0, n), 0, seq, 0).payload

  it('hands back each block with the number of blocks lost before it', () => {
    const a = new AdpcmAssembler()
    const first = a.push(block(0))
    expect(first).toMatchObject({ kind: 'block', gap: 0 })
    const third = a.push(block(3))
    expect(third).toMatchObject({ kind: 'block', gap: 2 })
    expect(a.nextSeq).toBe(4)
    expect(a.stats).toEqual({ blocks: 2, gapBlocks: 2, duplicates: 0, bad: 0 })
  })

  it('assembling inserts exactly gap x 505 zero samples', () => {
    for (const gap of [1, 2, 50]) {
      const pcm = assembleAdpcm([block(0), block(1 + gap)])
      expect(pcm.length).toBe((1 + gap + 1) * ADPCM_BLOCK_PCM_BYTES)
      const zeros = pcm.subarray(ADPCM_BLOCK_PCM_BYTES, (1 + gap) * ADPCM_BLOCK_PCM_BYTES)
      expect(zeros.every(b => b === 0)).toBe(true)
    }
  })

  it('drops a repeated or older sequence number and counts it', () => {
    const a = new AdpcmAssembler()
    a.push(block(0)); a.push(block(1)); a.push(block(2))
    expect(a.push(block(1))).toEqual({ kind: 'duplicate' })
    expect(a.push(block(2))).toEqual({ kind: 'duplicate' })
    expect(a.push(block(0))).toEqual({ kind: 'duplicate' })
    expect(a.nextSeq).toBe(3)
    expect(a.stats.duplicates).toBe(3)
  })

  it('counts a malformed block and keeps its place', () => {
    const a = new AdpcmAssembler()
    a.push(block(0))
    expect(a.push(Uint8Array.from([1, 2, 3]))).toEqual({ kind: 'bad', reason: 'short' })
    expect(a.push(block(1)).kind).toBe('block')
    expect(a.stats).toMatchObject({ blocks: 2, bad: 1 })
  })

  it('a block with a lost first sequence number counts the loss, and reset starts a new turn', () => {
    const a = new AdpcmAssembler()
    expect(a.push(block(1))).toMatchObject({ kind: 'block', gap: 1 })
    a.reset()
    expect(a.nextSeq).toBe(0)
    expect(a.stats).toEqual({ blocks: 0, gapBlocks: 0, duplicates: 0, bad: 0 })
    expect(a.push(block(0))).toMatchObject({ kind: 'block', gap: 0 })
  })

  it('a short last block decodes to its own length', () => {
    const a = new AdpcmAssembler()
    const r = a.push(block(0, 100))
    expect(r.kind === 'block' && r.pcm.length).toBe(200)
  })

  it('the prefix is 5 bytes and the WAV block 4 + 4k', () => {
    expect(ADPCM_PREFIX_BYTES).toBe(5)
    expect(block(0).length).toBe(261)
  })
})
